// Original revision prompts organised against Pearson Edexcel 1HI0 and AQA 8035.
// Rows: question, key fact, explanation, exam practice, topic. IDs stay stable.
(() => {
  const decks = window.FLASHCARD_DATA.subjects.flatMap(subject => subject.decks);
  // Include initial cards when filtering by the broader curriculum topics.
  const initialTopics = {
    'cw-01':'Origins 1941–58','cw-02':'Origins 1941–58','cw-03':'Origins 1941–58','cw-04':'Origins 1941–58','cw-05':'Crises 1958–70','cw-06':'End of the Cold War 1970–91',
    'med-01':'Medieval c1250–1500','med-02':'Renaissance c1500–1700','med-03':'Renaissance c1500–1700','med-04':'Industrial c1700–1900','med-05':'Modern c1900–present','med-06':'Modern c1900–present',
    'geo-haz-01':'Tectonics','geo-haz-02':'Hazard management','geo-haz-03':'Tropical storms','geo-haz-04':'Hazard management','geo-haz-05':'Climate management',
    'geo-live-01':'Ecosystems','geo-live-02':'Rainforests','geo-live-03':'Rainforests','geo-live-04':'Rainforest management','geo-live-05':'Course options',
    'geo-uk-01':'UK overview','geo-uk-02':'Coasts — option','geo-uk-03':'Coasts — option','geo-uk-04':'Rivers — option','geo-uk-05':'Rivers — option'
  };
  decks.forEach(deck => deck.cards.forEach(card => { if (initialTopics[card.id]) card.tags = [initialTopics[card.id]]; }));
  const add = (deckId, rows) => {
    const deck = decks.find(item => item.id === deckId);
    rows.forEach(([question, quote, answer, exam, topic], i) => deck.cards.push({
      id: `${deckId}-expanded-${i + 1}`, question, quote, answer, exam, tags: [topic]
    }));
  };
  add('cold-war', [
    ['Why did the Grand Alliance form in 1941?', 'A shared enemy: Nazi Germany', 'Britain, the USSR and the USA cooperated to defeat the Axis. Their alliance rested on military necessity, so ideological disagreements became harder to contain once Germany was defeated.', 'Explain why cooperation during war did not guarantee cooperation afterwards.', 'Origins 1941–58'],
    ['What was agreed at Tehran in 1943?', 'A second front in Western Europe', 'Roosevelt and Churchill agreed to open a second front against Germany. This would reduce pressure on Soviet forces and showed the Allies could coordinate military strategy.', 'Connect an agreement to its effect on relations.', 'Origins 1941–58'],
    ['What did the leaders agree at Yalta in February 1945?', 'Occupation zones and a post-war settlement', 'Germany would be divided into occupation zones. The leaders supported the United Nations and promised free elections in liberated Europe, but different interpretations of freedom left future disputes unresolved.', 'Distinguish the agreement from later disputes over implementing it.', 'Origins 1941–58'],
    ['Why were relations worse at Potsdam in July–August 1945?', 'New leaders and growing suspicion', 'Truman replaced Roosevelt; Britain changed from Churchill to Attlee during the conference. Soviet control in Eastern Europe and disagreements about reparations increased tension. The US atomic test also changed the balance of power.', 'Develop two causes rather than listing leaders.', 'Origins 1941–58'],
    ['Why did the atomic bomb increase tension?', 'The USA initially held a nuclear monopoly', 'The bomb gave the USA exceptional destructive power and increased Soviet insecurity. The USSR tested its own atomic bomb in 1949, ending the monopoly and accelerating an arms race.', 'Link a military development to mistrust or policy.', 'Origins 1941–58'],
    ['What did Kennan argue in the Long Telegram?', 'February 1946: resist Soviet expansion', 'Kennan portrayed Soviet leaders as hostile to capitalism and expansionist, but responsive to firm resistance. His analysis helped US policymakers see containment as necessary.', 'Explain how an interpretation influenced policy.', 'Origins 1941–58'],
    ['What did the Novikov Telegram argue?', 'September 1946: fear of US domination', 'Novikov claimed the USA sought worldwide dominance and was building military strength. The telegram reinforced Soviet suspicions, mirroring American fears of Soviet expansion.', 'Compare the two telegrams as evidence of mutual distrust.', 'Origins 1941–58'],
    ['Why did Stalin establish satellite states?', 'A protective buffer and Soviet influence', 'Communist governments loyal to Moscow limited Western influence on the Soviet border. Stalin presented this as security, while Western leaders saw the suppression of political choice as expansion.', 'Show both viewpoints without treating either as neutral fact.', 'Origins 1941–58'],
    ['What was Cominform?', '1947: coordination of communist parties', 'Cominform encouraged communist parties to follow Moscow’s political line. It strengthened Soviet influence and organised opposition to Western policies such as Marshall aid.', 'Keep political coordination separate from Comecon’s economic role.', 'Origins 1941–58'],
    ['What was Comecon?', '1949: economic cooperation in the Soviet bloc', 'Comecon linked communist economies through trade and planning. It offered an alternative to Western economic cooperation and reinforced the division of Europe.', 'Explain one economic and one political consequence.', 'Origins 1941–58'],
    ['Why was NATO formed in 1949?', 'Collective defence', 'Members agreed that an attack on one would be treated as an attack on all. The alliance tied the USA to Western European defence and made the division of Europe military as well as political.', 'Use the Berlin crisis as context for Western insecurity.', 'Origins 1941–58'],
    ['Why was the Warsaw Pact formed in 1955?', 'West Germany joined NATO', 'The USSR organised its Eastern European allies into a military alliance after West Germany entered NATO. It formalised Soviet leadership and the armed division of Europe.', 'Link trigger → response → consequence.', 'Origins 1941–58'],
    ['Why did the Hungarian Uprising begin in 1956?', 'Resentment of Soviet control', 'Political repression, poor living standards and resentment of Soviet influence fuelled protest. Khrushchev’s criticism of Stalin encouraged hopes that reform would be tolerated.', 'Separate long-term grievances from the immediate encouragement.', 'Origins 1941–58'],
    ['Why did Soviet troops crush Nagy’s reforms?', 'Withdrawal from the Warsaw Pact threatened Soviet control', 'Nagy promised reforms and announced Hungarian neutrality. Soviet leaders feared losing a strategic ally and encouraging other states to leave their sphere; troops invaded in November 1956.', 'Explain why a reform became a strategic threat.', 'Origins 1941–58'],
    ['Why did the West not intervene militarily in Hungary?', 'Risk of direct war with the USSR', 'Western states condemned the invasion but Hungary lay within the Soviet sphere. Military action risked a wider war, while the Suez Crisis also divided Western attention.', 'Distinguish condemnation from effective intervention.', 'Origins 1941–58'],
    ['What was Khrushchev’s Berlin ultimatum in 1958?', 'A demand for Western withdrawal', 'Khrushchev demanded that Western forces leave Berlin within six months and proposed a free city. Refugees escaping through West Berlin were weakening East Germany’s economy and reputation.', 'Link the refugee problem to the ultimatum.', 'Crises 1958–70'],
    ['Why did the Paris summit collapse in 1960?', 'The U-2 spy-plane incident', 'A US U-2 aircraft was shot down over the USSR shortly before the summit. Eisenhower accepted responsibility for the spying programme but would not give the apology Khrushchev demanded.', 'Explain how the incident damaged trust and negotiations.', 'Crises 1958–70'],
    ['Why was the Berlin Wall built in August 1961?', 'Stop emigration through West Berlin', 'East Germany was losing workers and professionals. Sealing the border stopped most departures and stabilised the regime, but divided families and exposed the coercion needed to retain citizens.', 'Develop both domestic and international consequences.', 'Crises 1958–70'],
    ['Why did Kennedy accept the Wall’s existence?', 'Access to West Berlin remained', 'Kennedy opposed the division but did not tear the Wall down. Western access and the Western presence in Berlin continued, allowing the USA to avoid direct military conflict while defending West Berlin.', 'Explain why a tense outcome could still reduce an immediate risk.', 'Crises 1958–70'],
    ['What was the Bay of Pigs invasion?', 'April 1961: failed invasion by Cuban exiles', 'US-backed exiles tried to overthrow Castro but were defeated. The failure embarrassed Kennedy and pushed Castro towards stronger Soviet protection.', 'Link the failure to Cuba’s willingness to accept Soviet support.', 'Crises 1958–70'],
    ['Why did Khrushchev place missiles in Cuba?', 'Protect Cuba and improve the strategic balance', 'Missiles could deter another invasion of Cuba and threaten the USA from nearby. They also countered US nuclear advantages and American missiles stationed close to the USSR.', 'Explain motives rather than retelling the crisis.', 'Crises 1958–70'],
    ['What did the 1963 Limited Test Ban Treaty do?', 'Restricted where nuclear tests could take place', 'It banned tests in the atmosphere, outer space and underwater for its parties. Underground tests remained possible, so it reduced some dangers without ending nuclear competition.', 'Balance achievement with limitation.', 'Crises 1958–70'],
    ['What did the Outer Space Treaty and Non-Proliferation Treaty address?', '1967: space; 1968: nuclear spread', 'The Outer Space Treaty prohibited placing nuclear weapons in orbit or on celestial bodies. The Non-Proliferation Treaty sought to prevent more states acquiring nuclear weapons while supporting peaceful nuclear cooperation.', 'Distinguish preventing spread from eliminating existing arsenals.', 'Crises 1958–70'],
    ['What was the Prague Spring?', 'Dubček’s reforms in Czechoslovakia, 1968', 'Dubček relaxed censorship and sought socialism with greater freedom. He did not initially aim to abandon communism, but Moscow feared that liberalisation would undermine control across its bloc.', 'Explain why Moscow feared reforms despite continued socialism.', 'Crises 1958–70'],
    ['What was the Brezhnev Doctrine?', 'Limited sovereignty for communist allies', 'After the invasion of Czechoslovakia, Soviet leaders asserted a right to intervene where socialism was threatened. It signalled that Eastern European states could not freely choose a different political course.', 'Link doctrine to the military action it justified.', 'Crises 1958–70'],
    ['Why did détente develop in the 1970s?', 'Reduce danger and the cost of competition', 'Nuclear confrontation and expensive military spending encouraged negotiation. Both powers sought greater security, while economic and diplomatic interests made cooperation worthwhile.', 'Détente means easing tension, not the end of rivalry.', 'End of the Cold War 1970–91'],
    ['What did SALT I achieve in 1972?', 'Limits on some strategic weapons', 'The agreements restricted anti-ballistic missile systems and froze some missile launcher numbers. They did not abolish nuclear weapons or stop all technological improvements.', 'Explain why an agreement could be significant but incomplete.', 'End of the Cold War 1970–91'],
    ['Why were the Helsinki Accords important in 1975?', 'Security, cooperation and human rights', 'The agreements recognised European frontiers and encouraged cooperation. Human-rights commitments gave critics of communist governments a standard against which to judge them.', 'Show different benefits for Eastern and Western leaders.', 'End of the Cold War 1970–91'],
    ['Why did the Soviet invasion of Afghanistan damage détente?', 'December 1979: intervention to support a communist regime', 'The USA saw the invasion as expansion towards a strategically important region. Relations worsened, SALT II ratification stalled, and sanctions and sporting boycotts followed.', 'Build a causal chain rather than listing disconnected events.', 'End of the Cold War 1970–91'],
    ['What was the Carter Doctrine?', '1980: defend US interests in the Persian Gulf', 'Carter warned that attempts by outside powers to control the Persian Gulf would be resisted, including by force. The doctrine reflected fears about oil supplies and Soviet expansion.', 'Connect the doctrine to the Afghanistan crisis.', 'End of the Cold War 1970–91'],
    ['How did Olympic boycotts reflect the Second Cold War?', 'Moscow 1980; Los Angeles 1984', 'The USA led a boycott of the Moscow Games after Afghanistan. The USSR and many allies boycotted Los Angeles in 1984, showing how rivalry extended beyond military affairs.', 'Use the dates accurately and explain symbolic impact.', 'End of the Cold War 1970–91'],
    ['Why did Reagan’s SDI concern the USSR?', '1983: a proposed missile-defence system', 'A successful shield could weaken the Soviet nuclear deterrent. Matching the proposed technology would be costly for the USSR, adding pressure to an already strained economy.', 'Distinguish the proposal’s strategic effect from a fully operating shield.', 'End of the Cold War 1970–91'],
    ['What were glasnost and perestroika?', 'Openness and restructuring', 'Gorbachev encouraged greater openness in public debate and tried to reform the Soviet economy. These changes exposed problems and loosened controls without reliably fixing shortages or political tensions.', 'Explain the unintended effects of reform.', 'End of the Cold War 1970–91'],
    ['Why was the INF Treaty significant in 1987?', 'An entire category of missiles was removed', 'Reagan and Gorbachev agreed to eliminate their ground-launched intermediate-range and shorter-range nuclear missiles covered by the treaty. Verification helped build trust beyond simply limiting growth.', 'Compare elimination with the more limited approach of SALT.', 'End of the Cold War 1970–91'],
    ['How did Gorbachev’s approach affect Eastern Europe?', 'Reduced willingness to enforce control by invasion', 'Reform movements could challenge communist governments with less fear of Soviet military intervention. This helped the rapid political changes of 1989 and the collapse of the Soviet bloc.', 'Compare 1989 with Hungary in 1956 or Czechoslovakia in 1968.', 'End of the Cold War 1970–91'],
    ['What ended in 1991, and in what order?', 'Warsaw Pact first; Soviet Union later', 'The Warsaw Pact was dissolved in 1991 as communist control in Eastern Europe collapsed. The Soviet Union itself dissolved in December after a failed coup and growing independence movements.', 'Do not reverse the chronology when explaining the end of the Cold War.', 'End of the Cold War 1970–91'],
    ['How do you write an analytical narrative?', 'Chronology plus causal links', 'Select relevant events in order and explain how each development led to the next. A sequence of dates alone does not explain why the outcome happened.', 'Practise three connected stages of the Berlin crisis or Cuban Missile Crisis.', 'Exam practice']
  ]);
  add('medicine', [
    ['Why did medieval people see disease as religious?', 'God, sin and punishment', 'Christian belief shaped explanations of illness. Prayer, pilgrimage and repentance seemed logical responses when illness was understood as divine punishment or a test of faith.', 'Connect belief about cause to treatment.', 'Medieval c1250–1500'],
    ['What was miasma?', 'Bad air believed to cause disease', 'People linked illness to foul smells and decaying matter. Cleaning streets or burning pleasant-smelling substances could therefore be used as prevention, although the explanation was incorrect.', 'An incorrect theory could still lead to some useful action.', 'Medieval c1250–1500'],
    ['How did Galen’s Theory of Opposites guide treatment?', 'Counter an imbalance with its opposite', 'If a patient seemed too cold, a physician might prescribe warming foods or remedies. This developed the Four Humours into a practical system that appeared to explain many symptoms.', 'Use a specific example when explaining treatment.', 'Medieval c1250–1500'],
    ['Who provided medieval medical care?', 'Physicians, apothecaries, surgeons and households', 'University-trained physicians were expensive. Apothecaries sold remedies; barber-surgeons performed practical procedures. Much everyday nursing and treatment took place within families.', 'Compare roles rather than calling every healer a doctor.', 'Medieval c1250–1500'],
    ['What did medieval hospitals mainly provide?', 'Care, rest, food and spiritual support', 'Many hospitals were religious institutions focused on comfort and care. They were not modern centres of curative surgery, and some excluded infectious patients to protect others.', 'Separate care from effective cure.', 'Medieval c1250–1500'],
    ['How did people respond to the Black Death of 1348–49?', 'Responses reflected existing beliefs', 'People prayed, used bloodletting, carried scented herbs or tried to avoid infected places. Religious, humoral and miasma explanations prevented a clear understanding of transmission.', 'Explain a response using the belief behind it.', 'Medieval c1250–1500'],
    ['Why did medical ideas change slowly in the Middle Ages?', 'Authority and limited testing', 'Galen’s long-standing reputation, Church influence and limited scientific equipment encouraged continuity. Observing a symptom did not reveal microorganisms or provide a reliable way to test competing causes.', 'Develop the mechanism by which a factor slowed change.', 'Medieval c1250–1500'],
    ['How did printing help Renaissance medicine?', 'Ideas and illustrations reached more readers', 'Printed books spread anatomical diagrams and challenges to established authorities more quickly. However, printing also reproduced old theories, so it did not automatically produce progress.', 'Evaluate a factor through both change and continuity.', 'Renaissance c1500–1700'],
    ['What was the Royal Society’s contribution?', 'From 1660: observation, experiment and communication', 'Members discussed experiments and published findings, encouraging evidence rather than unquestioned authority. Sharing work allowed discoveries to be checked and developed by others.', 'Link institutions to scientific method and communication.', 'Renaissance c1500–1700'],
    ['What changed in responses to the Great Plague of 1665?', 'More organised local action', 'Authorities used quarantine, marked infected houses, restricted gatherings and attempted street cleaning. Older religious and miasma explanations remained, so change in organisation exceeded change in understanding.', 'Compare with 1348–49 using a clear similarity and difference.', 'Renaissance c1500–1700'],
    ['Why did Harvey’s discovery have limited immediate effect?', 'Better explanation did not immediately mean better cures', 'Doctors could not yet see the capillaries connecting arteries and veins, and some resisted a challenge to Galen. Understanding circulation offered few immediate treatments for everyday illness.', 'Distinguish short-term impact from long-term significance.', 'Renaissance c1500–1700'],
    ['How did Sydenham change the study of disease?', 'Careful observation of symptoms', 'Sydenham encouraged doctors to identify diseases through consistent patterns of symptoms, rather than treating every illness as a unique humoral imbalance. He still lacked germ knowledge.', 'Show a change in method without exaggerating a complete revolution.', 'Renaissance c1500–1700'],
    ['What did Jenner demonstrate in 1796?', 'Cowpox could protect against smallpox', 'Jenner used cowpox material and tested protection against smallpox. Vaccination was safer than smallpox inoculation but met resistance and initially lacked a scientific explanation.', 'Explain why acceptance and discovery are different stages.', 'Industrial c1700–1900'],
    ['Why did some people oppose vaccination?', 'Risk, mistrust and loss of income', 'People feared an unfamiliar treatment using animal material; inoculators could lose business. Some also objected to government compulsion, even as evidence for vaccination accumulated.', 'Use specific reasons rather than saying people feared change.', 'Industrial c1700–1900'],
    ['How did Koch build on germ theory?', 'Specific microorganisms linked to specific diseases', 'Koch used laboratory methods to isolate and identify bacteria, including those causing tuberculosis and cholera. Staining and culture techniques made microbes easier to study.', 'Compare Pasteur’s broad theory with Koch’s identification work.', 'Industrial c1700–1900'],
    ['Why was John Snow’s work on cholera significant?', 'Broad Street, London, 1854', 'Snow mapped cholera cases and connected them with contaminated water from a pump. Removing the handle addressed a source of infection before germ theory was widely accepted.', 'Explain both his evidence and why contemporaries could resist it.', 'Industrial c1700–1900'],
    ['How did the Public Health Acts of 1848 and 1875 differ?', 'Permissive action became compulsory duties', 'The 1848 Act allowed local improvements but was limited in enforcement. The 1875 Act imposed stronger duties for sanitation, drainage and water provision, expanding state responsibility.', 'Use the distinction to explain government change.', 'Industrial c1700–1900'],
    ['What did James Simpson contribute in 1847?', 'Chloroform as an anaesthetic', 'Chloroform reduced pain during operations, allowing longer procedures. Dosage risks and continued infection meant anaesthesia did not solve all the dangers of surgery.', 'Explain why solving pain could expose other problems.', 'Industrial c1700–1900'],
    ['How did Lister reduce surgical infection?', 'Carbolic acid antisepsis in the 1860s', 'Inspired by germ theory, Lister used carbolic acid to kill microbes around wounds and operations. Adoption faced resistance because the method was awkward and irritating.', 'Link scientific theory to a practical application.', 'Industrial c1700–1900'],
    ['What is the difference between antiseptic and aseptic surgery?', 'Kill microbes versus prevent their entry', 'Antiseptic methods destroy germs present in wounds or the operating environment. Aseptic surgery uses sterilised equipment, clean clothing and controlled conditions to keep germs away in the first place.', 'Use a concrete example for each.', 'Industrial c1700–1900'],
    ['How did Florence Nightingale improve nursing?', 'Training and hospital standards', 'Nightingale promoted cleanliness, ventilation, organisation and trained nurses. Her work improved care even though her early understanding of disease relied on miasma rather than germs.', 'A person can improve practice without a correct theory.', 'Industrial c1700–1900'],
    ['What was a magic bullet?', 'A drug targeting a particular pathogen', 'Researchers sought chemicals that would kill disease-causing organisms without seriously harming the patient. Salvarsan 606, developed through Ehrlich’s research team, treated syphilis.', 'Distinguish targeted chemical treatment from vaccination.', 'Modern c1900–present'],
    ['Why did penicillin take years to become widely available?', 'Development and production were essential', 'The substance had to be purified, tested and produced in enough quantity. Florey and Chain’s team, government funding and US industry transformed a laboratory observation into a usable medicine.', 'Explain how factors combined rather than awarding all credit to one person.', 'Modern c1900–present'],
    ['How did DNA research change explanations of illness?', 'Inherited information can influence disease', 'Understanding DNA structure and later genetic research helped identify inherited conditions and risks. This complemented germ theory because many illnesses are not caused by infection.', 'Compare genetic, lifestyle and infectious causes.', 'Modern c1900–present'],
    ['Why has lung cancer become a public-health focus?', 'Smoking is a major preventable risk', 'Research linked tobacco use to lung cancer. Education, restrictions on advertising and smoke-free laws aim to reduce exposure; diagnosis and treatment have also developed.', 'Classify actions as prevention, diagnosis or treatment.', 'Modern c1900–present'],
    ['How have diagnostic technologies changed medicine?', 'Seeing inside the body', 'X-rays and later scans let doctors identify internal problems more accurately. Better diagnosis helps treatment decisions, but access, cost and the available treatment still affect outcomes.', 'Explain an impact rather than only naming equipment.', 'Modern c1900–present'],
    ['Why were wounds on the Western Front prone to infection?', 'Deep injuries carried contaminated material', 'Shell fragments drove clothing and soil into wounds. Manured farmland contained bacteria, while delays in evacuation gave infection time to develop.', 'Link weapon → wound → terrain → infection.', 'Western Front 1914–18'],
    ['What was trench foot?', 'Prolonged exposure to cold, wet conditions', 'Wet feet and poor circulation damaged tissue and could lead to gangrene. Dry socks, inspections, rubbing feet and improved drainage helped prevention.', 'Explain why trench conditions made routine prevention difficult.', 'Western Front 1914–18'],
    ['How did gas attacks affect soldiers?', 'Different gases caused different injuries', 'Chlorine and phosgene damaged breathing; mustard gas caused severe blistering and eye injuries. Protective equipment improved, but gas complicated treatment and caused lasting harm.', 'Avoid describing every gas as having identical effects.', 'Western Front 1914–18'],
    ['What was the chain of evacuation?', 'From front-line first aid to specialist hospitals', 'A typical route ran from a regimental aid post through dressing stations to a casualty clearing station and then a base hospital. Severity, capacity and transport affected the route.', 'Field ambulances were medical units, not just vehicles.', 'Western Front 1914–18'],
    ['Why was evacuation difficult?', 'Mud, shellfire and damaged routes', 'Stretcher-bearers moved slowly through dangerous ground. Roads could be destroyed or congested, limiting horse and motor ambulances and delaying care.', 'Explain how a transport problem changed medical outcomes.', 'Western Front 1914–18'],
    ['Why was the Thomas splint important?', 'Stabilising fractured thigh bones', 'The splint reduced movement, bleeding and further tissue damage during evacuation. More widespread use greatly improved survival for this injury.', 'Explain the mechanism instead of relying on a memorised statistic.', 'Western Front 1914–18'],
    ['Why were X-rays useful and difficult near the front?', 'Locating fragments and broken bones', 'X-rays helped surgeons find shrapnel before operating. Machines needed power, were fragile and could overheat; conditions near the fighting restricted their use.', 'Give a benefit and a practical limitation.', 'Western Front 1914–18'],
    ['How did blood transfusions improve during the war?', 'Typing, storage and anticoagulants', 'Knowledge of blood groups reduced incompatible transfusions. Sodium citrate prevented clotting and storage techniques made blood available without always needing a donor beside the patient.', 'Link laboratory developments to emergency treatment.', 'Western Front 1914–18'],
    ['How were infected wounds treated before antibiotics?', 'Removing damaged tissue and cleaning wounds', 'Surgeons removed dead or contaminated tissue through debridement. Antiseptic irrigation, including the Carrel–Dakin method, helped manage infection; severe cases could require amputation.', 'Do not place penicillin in routine First World War treatment.', 'Western Front 1914–18'],
    ['Why did Arras’s underground hospital matter?', 'Shelter and organised treatment near the front', 'Underground space offered protection from shelling and capacity for casualties. Its usefulness still depended on access, water, supplies and moving wounded soldiers through the system.', 'Link the environment to treatment opportunities and constraints.', 'Western Front 1914–18'],
    ['How should you evaluate the usefulness of a medical source?', 'Content, provenance and contextual knowledge', 'Explain what the source reveals about the enquiry, check it against relevant knowledge and consider how its creator, purpose and circumstances shape its evidence. Bias does not automatically make it useless.', 'Make every judgement specific to the question and source.', 'Exam practice'],
    ['How do you explain change across medical periods?', 'Compare like with like', 'Choose the same aspect, such as causes, treatment or prevention, in each period. Support a difference or continuity with precise examples, then explain why it occurred.', 'Practise comparing prevention in 1348–49 and 1665.', 'Exam practice']
  ]);
  add('natural-hazards', [
    ['What makes a natural event a hazard?', 'Potential harm to people or property', 'A physical event becomes a hazard where it threatens people, livelihoods or property. Risk depends on exposure and vulnerability as well as the event’s size.', 'Explain why the same event can have different impacts in different places.', 'Hazard risk'],
    ['What happens at a constructive plate margin?', 'Plates move apart', 'Magma rises into the gap and cools to form new crust. Movement causes shallow earthquakes; relatively fluid basaltic lava commonly produces less explosive eruptions.', 'Link movement to both crust creation and hazards.', 'Tectonics'],
    ['What happens at a destructive plate margin?', 'Oceanic lithosphere is subducted', 'A denser oceanic plate sinks beneath another plate. Friction produces earthquakes; water released from the sinking plate helps melting above it, generating magma that may feed explosive volcanoes.', 'Avoid saying friction alone melts the whole plate.', 'Tectonics'],
    ['Why do conservative margins have earthquakes but no typical volcanoes?', 'Plates slide past one another', 'Friction can lock the plates until stress is released suddenly. No crust is created or subducted, so there is no usual mechanism producing magma at the boundary.', 'Explain both the presence of earthquakes and absence of volcanoes.', 'Tectonics'],
    ['How are focus and epicentre different?', 'Origin below ground; position above it', 'The focus is where an earthquake begins inside the Earth. The epicentre is the point on the surface directly above it.', 'Label a simple diagram from memory.', 'Tectonics'],
    ['Why can wealth affect earthquake losses?', 'Vulnerability and capacity to respond', 'Stronger buildings, enforced codes, healthcare and emergency access can reduce casualties. Wealth does not remove risk: magnitude, depth, population density and time of day also matter.', 'Compare named events using more than national income.', 'Tectonics'],
    ['Why do people live near volcanoes?', 'Benefits and constraints', 'Fertile soils, tourism, geothermal energy and jobs can attract settlement. Family ties, perceived low risk and lack of money to move may also keep people there.', 'Explain two distinct reasons.', 'Tectonics'],
    ['Can earthquakes be predicted precisely?', 'No reliable exact prediction', 'Scientists map risk and monitor movement, but cannot reliably predict a precise time, place and magnitude. Preparedness and resilient buildings therefore remain essential.', 'Distinguish long-term risk estimates from exact predictions.', 'Tectonics'],
    ['How does the Hadley cell affect climate?', 'Rising air near 0°; sinking air near 30°', 'Strong heating near the Equator makes moist air rise, cool and produce rainfall. Drier air descends around the subtropics, creating higher pressure and many desert climates.', 'Use pressure and vertical air movement in your explanation.', 'Atmospheric circulation'],
    ['What distinguishes the eye and eyewall of a tropical storm?', 'Calm centre; most intense surrounding weather', 'Air sinks in the eye, often producing calmer conditions. The eyewall contains vigorous rising air, towering clouds, intense rain and very strong winds.', 'Describe a journey through the storm’s cross-section.', 'Tropical storms'],
    ['Why do tropical storms weaken over land?', 'Loss of heat and moisture supply', 'They lose access to warm ocean water that fuels evaporation. Greater surface friction also disrupts circulation.', 'Link each condition to reduced energy.', 'Tropical storms'],
    ['What is a storm surge?', 'A temporary rise in sea level', 'Powerful winds push seawater towards the coast, with low pressure also contributing. A surge can flood low-lying land, especially when combined with a high tide.', 'Distinguish storm surge from heavy-rain river flooding.', 'Tropical storms'],
    ['How might warming affect tropical storms?', 'Greater intensity and heavier rainfall are key concerns', 'Warmer water can supply more energy and warmer air can hold more moisture. Changes in total storm frequency and location are complex; more warmth does not prove more storms everywhere.', 'Use qualified predictions and explain the physical link.', 'Tropical storms'],
    ['How do immediate and long-term responses differ?', 'Emergency needs versus rebuilding and resilience', 'Search and rescue, shelter and medical aid address urgent needs. Rebuilding infrastructure and improving protection take longer and aim to restore livelihoods or reduce future risk.', 'Organise a named example into effects and responses.', 'Hazard management'],
    ['What weather hazards affect the UK?', 'Storms, flooding, heatwaves, drought, snow and ice', 'Different atmospheric conditions generate different hazards. Heavy rain may flood rivers, prolonged dry weather can reduce water supplies, and freezing conditions disrupt travel.', 'Explain an impact through the process causing it.', 'UK weather'],
    ['Why can prolonged rain cause flooding?', 'Soils become saturated', 'Once stores are full, infiltration decreases and more rain becomes surface runoff. Water reaches channels quickly and discharge can exceed channel capacity.', 'Connect rainfall, stores, runoff and discharge.', 'UK weather'],
    ['What evidence is needed to claim UK weather is more extreme?', 'Long records and trends', 'One unusual storm cannot establish a trend. Compare frequency or intensity across a long dataset and consider measurement quality and natural variability.', 'Use figures from a graph and avoid unsupported generalisation.', 'UK weather'],
    ['What evidence reveals past climates?', 'Ice cores, tree rings and other proxy records', 'Air bubbles in ice preserve past atmospheric gases; isotopes help reconstruct temperatures. Tree growth and pollen records also reveal environmental conditions, though each proxy has limits.', 'Explain what the evidence records, not just its name.', 'Climate change'],
    ['How do fossil fuels enhance the greenhouse effect?', 'More carbon dioxide traps more outgoing heat', 'Burning fossil fuels releases stored carbon. Extra greenhouse gases absorb outgoing infrared radiation and re-emit it, increasing warming in the lower atmosphere.', 'Distinguish the natural effect from human enhancement.', 'Climate change'],
    ['How does deforestation contribute to warming?', 'Emissions and reduced carbon uptake', 'Burning or decomposing vegetation releases carbon dioxide. Removing trees also reduces future absorption through photosynthesis.', 'Develop both parts of the explanation.', 'Climate change'],
    ['How can volcanic eruptions affect climate?', 'Some cause short-term cooling', 'Large eruptions can inject sulphur dioxide into the stratosphere. Reflective aerosols then reduce incoming sunlight for a time; this differs from long-term greenhouse warming.', 'Do not claim all eruptions have the same global impact.', 'Climate change'],
    ['What are orbital variations?', 'Changes in Earth’s orbit, tilt and wobble', 'These change the distribution of solar energy over long timescales and help explain glacial cycles. They do not explain the rapid recent warming attributed mainly to human activity.', 'Use appropriate timescales.', 'Climate change'],
    ['Why does sea level rise with warming?', 'Thermal expansion and melting land ice', 'Warmer seawater expands. Melting glaciers and ice sheets add water to oceans; floating sea ice has little direct effect on sea level when it melts.', 'Separate land ice from sea ice.', 'Climate change'],
    ['How can water supplies adapt to climate change?', 'Conserve, store and diversify', 'Leak reduction and metering can reduce demand. Reservoirs, recycling and transfers can increase reliability, but involve costs and possible environmental conflicts.', 'Evaluate a strategy rather than assuming it solves every drought.', 'Climate management'],
    ['What makes a strong named hazard example?', 'Place-specific evidence linked to the question', 'Recall location, date, causes, primary and secondary effects, and immediate and longer-term responses. Use your class’s named examples and check any statistics against the organiser.', 'Practise explaining why two places experienced different outcomes.', 'Case-study practice']
  ]);
  add('living-world', [
    ['What are biotic and abiotic components?', 'Living and non-living parts', 'Plants, animals and decomposers are biotic. Light, temperature, water and minerals are abiotic; changes in either group affect the other.', 'Use a pond or woodland example to explain a link.', 'Ecosystems'],
    ['How does a food web differ from a food chain?', 'Many connected feeding relationships', 'A chain shows one pathway of energy transfer. A web shows several, so a change in one species can affect many predators and prey.', 'Explain a knock-on effect rather than just naming organisms.', 'Ecosystems'],
    ['What role do decomposers play?', 'Return nutrients to the system', 'Bacteria and fungi break down dead organisms and waste. Nutrients return to soil or water for plants to absorb, while energy is lost as heat rather than recycled.', 'Keep nutrient cycling separate from energy flow.', 'Ecosystems'],
    ['Where are major global biomes found?', 'Climate controls broad patterns', 'Rainforests cluster near the Equator, many hot deserts near the subtropics, temperate forests in mid-latitudes and tundra at high latitudes. Local factors modify these patterns.', 'Describe distribution with latitude and named regions.', 'Ecosystems'],
    ['How do rainforest plants compete for light?', 'Height, climbing and large leaves', 'Tall trees reach the canopy; lianas climb towards sunlight. Shade-tolerant plants may have large leaves to capture limited light below the canopy.', 'Link each adaptation to the condition it addresses.', 'Rainforests'],
    ['Why do some rainforest trees have buttress roots?', 'Support for tall trees', 'Wide roots support a tall trunk in relatively shallow soil. Surface roots can also access nutrients concentrated near the rapidly decomposing litter.', 'Avoid describing all roots as deep.', 'Rainforests'],
    ['Why does clearing rainforest increase soil erosion?', 'Loss of interception and root binding', 'Canopies normally reduce raindrop impact and roots hold soil together. Clearance exposes soil to heavy rain and runoff, increasing the removal of fertile material.', 'Write a complete process chain.', 'Rainforests'],
    ['How can road building increase deforestation beyond the road itself?', 'Access encourages further development', 'Roads allow logging, farming, mining and settlement to spread into previously inaccessible forest. The indirect area affected can exceed the initial cleared corridor.', 'Explain an indirect impact.', 'Rainforests'],
    ['Why can deforestation benefit some people?', 'Income, jobs, land and infrastructure', 'Timber, farming and mining can generate revenue and employment. These benefits must be compared with lost ecosystems, displacement and longer-term damage to soils and water.', 'Balance development benefits with environmental and social costs.', 'Rainforests'],
    ['How can selective logging improve sustainability?', 'Remove selected trees and allow recovery', 'Taking fewer trees and planning access routes can reduce canopy loss and soil damage. Replanting and enforcement matter; selective logging alone does not guarantee protection.', 'Evaluate conditions needed for success.', 'Rainforest management'],
    ['How can ecotourism protect rainforest?', 'Income depends on keeping the ecosystem intact', 'Local jobs and conservation fees can make standing forest valuable. Poorly managed visitor numbers, travel impacts or profits leaving the area can undermine the benefits.', 'Explain a benefit and limitation.', 'Rainforest management'],
    ['What is a debt-for-nature arrangement?', 'Debt relief linked to conservation', 'A creditor reduces debt in return for commitments to conservation. This can release money and reduce pressure to exploit forest, but outcomes depend on implementation.', 'Link financial incentives to environmental action.', 'Rainforest management'],
    ['Why are many hot deserts found near 30° latitude?', 'Descending air discourages rainfall', 'Air descending in the subtropical high-pressure belts warms and its relative humidity falls. Clouds are less likely to form, producing arid conditions.', 'Use the Hadley cell to explain the pattern.', 'Hot deserts — option'],
    ['How do cactus adaptations conserve water?', 'Spines, storage and a waxy surface', 'Spines reduce leaf area and water loss; fleshy stems store water. A waxy cuticle reduces evaporation, while root systems exploit scarce rain.', 'Explain function as well as naming the feature.', 'Hot deserts — option'],
    ['How can desert animals avoid heat stress?', 'Behaviour and water conservation', 'Nocturnal activity and burrowing reduce exposure to daytime heat. Physiological adaptations can minimise water loss, though features vary between species.', 'Use a specific animal studied in class.', 'Hot deserts — option'],
    ['What opportunities and challenges do hot deserts offer?', 'Resources and tourism, but difficult conditions', 'Minerals, solar energy, irrigated farming and tourism can create income. Extreme temperatures, water scarcity and remoteness raise costs and constrain development.', 'Develop an opportunity and its linked challenge.', 'Hot deserts — option'],
    ['How does overgrazing contribute to desertification?', 'Vegetation is removed faster than it regrows', 'Exposed soil is more vulnerable to wind and rain erosion. Loss of roots and organic matter can reduce water retention, making recovery harder.', 'Desertification is land degradation, not simply a desert moving.', 'Hot deserts — option'],
    ['How can appropriate technology reduce desertification?', 'Small-scale methods suited to local needs', 'Stone lines, water harvesting and efficient stoves can conserve soil, water or fuelwood. Affordability, maintenance and community involvement affect success.', 'Explain how one method interrupts a damaging cycle.', 'Hot deserts — option'],
    ['What is permafrost?', 'Ground frozen for at least two consecutive years', 'In tundra, a surface active layer can thaw in summer above permanently frozen ground. This affects drainage, root growth and the stability of buildings.', 'Connect the definition to an environmental consequence.', 'Cold environments — option'],
    ['How are tundra plants adapted?', 'Low growth and short growing seasons', 'Low plants avoid stronger winds and benefit from warmer air near the ground. Shallow roots suit the active layer, and rapid growth exploits the brief summer.', 'Link each feature to a named condition.', 'Cold environments — option'],
    ['Why is development difficult in cold environments?', 'Cold, remoteness and unstable thawing ground', 'Extreme temperatures affect workers and machinery. Transport and construction are expensive, while thawing permafrost can damage infrastructure.', 'Explain an economic consequence of a physical challenge.', 'Cold environments — option'],
    ['Why can cold ecosystems recover slowly from damage?', 'Slow growth and short seasons', 'Vegetation grows slowly and damaged ground may take years to recover. Disturbance can also thaw permafrost, altering drainage and habitats.', 'Use this to justify management rather than just saying the area is fragile.', 'Cold environments — option'],
    ['How can development and conservation be balanced in cold regions?', 'Design, regulation and protected areas', 'Raised infrastructure can limit heat transfer into permafrost; routes and seasonal restrictions can reduce disturbance. Monitoring and enforcement are needed alongside technology.', 'Evaluate a strategy using your named cold-environment case study.', 'Cold environments — option']
  ]);
  add('uk-landscapes', [
    ['Which UK landscape options do you revise?', 'Choose the two taught by your school', 'AQA offers coasts, rivers and glacial landscapes; your school teaches two. This deck labels each option so you can use the Topic filter and focus on the correct pair.', 'Confirm the pair and named examples from your organiser.', 'Course options'],
    ['How do constructive and destructive waves differ?', 'Swash and backwash balance', 'Constructive waves usually have stronger swash than backwash and build beaches. Destructive waves have stronger backwash and tend to remove sediment.', 'Link wave characteristics to the beach profile.', 'Coasts — option'],
    ['How do weathering and erosion differ?', 'Breakdown in place versus removal', 'Weathering breaks down rock where it is. Erosion wears away and removes material through moving water, ice or wind.', 'Keep freeze-thaw separate from wave erosion.', 'Coasts — option'],
    ['What is freeze-thaw weathering?', 'Water expands when it freezes', 'Water enters cracks, freezes and expands, forcing them wider. Repeated cycles weaken the rock until pieces break off.', 'The temperature must repeatedly cross freezing point.', 'Coasts — option'],
    ['What causes rotational slumping?', 'Saturated material slips along a curved surface', 'Water adds weight and reduces friction in weak material such as clay. A block rotates downslope, often where waves have undercut the cliff base.', 'Distinguish slumping from a sudden rockfall.', 'Coasts — option'],
    ['How does longshore drift move sediment?', 'Oblique swash and downhill backwash', 'Prevailing winds make waves approach at an angle. Swash moves material up the beach diagonally; gravity returns it more directly downslope, producing net movement along the coast.', 'Include the prevailing wind direction in a diagram.', 'Coasts — option'],
    ['How do headlands and bays form?', 'Differential erosion of rock bands', 'Less resistant rock erodes faster, creating bays. More resistant rock remains as projecting headlands, where wave energy may then become concentrated.', 'Connect geology to shape.', 'Coasts — option'],
    ['How does a wave-cut platform form?', 'Cliff undercutting and retreat', 'Waves erode a notch near the cliff base. Unsupported rock collapses and the cliff retreats, leaving a gently sloping platform exposed at low tide.', 'Explain the repeated cycle.', 'Coasts — option'],
    ['How does a spit form?', 'Deposition beyond a change in coastline direction', 'Longshore drift carries sediment along the coast. Where the coast turns or an estuary interrupts it, material is deposited into calmer water; changing winds can curve the end.', 'Explain why a river current may prevent full closure.', 'Coasts — option'],
    ['How does a bar differ from a spit?', 'A bar joins two sections of land', 'Continued deposition may extend a spit across a bay to the other side, forming a bar. A lagoon can develop behind it.', 'Describe the connection, not just the length.', 'Coasts — option'],
    ['How do sand dunes develop?', 'Wind-blown sand is trapped', 'Dry sand blows inland and collects around obstacles. Pioneer vegetation traps more sand; roots stabilise it and growing dunes create conditions for further succession.', 'Link wind, plants and sediment.', 'Coasts — option'],
    ['What are the benefits and costs of groynes?', 'Trap sediment but interrupt its supply', 'Groynes build a wider beach that absorbs wave energy. They can reduce sediment reaching places farther along the coast, increasing erosion there.', 'Evaluate effects beyond the protected location.', 'Coasts — option'],
    ['How do sea walls and rock armour protect coasts?', 'Resist or dissipate wave energy', 'Sea walls form a hard barrier but can be expensive and encourage scour. Rock armour absorbs energy through gaps, though transport costs and appearance can be drawbacks.', 'Compare two methods using the same criteria.', 'Coasts — option'],
    ['What is managed realignment?', 'Allow selected low-value land to flood', 'Defences are moved or breached to create intertidal habitat that can absorb wave energy. This can be sustainable but sacrifices land and may face opposition.', 'Discuss whose land and interests are affected.', 'Coasts — option'],
    ['How do rivers transport their load?', 'Traction, saltation, suspension and solution', 'Large particles roll; smaller stones bounce; fine sediment is carried within the water; dissolved minerals travel in solution.', 'Match a particle size to a process.', 'Rivers — option'],
    ['Why does a river deposit material?', 'It loses the capacity to carry its load', 'When velocity and energy fall, sediment may settle. Coarser material generally needs more energy to move and is often deposited before finer material.', 'Explain where and why flow slows.', 'Rivers — option'],
    ['How does a waterfall retreat to form a gorge?', 'Undercutting, collapse and upstream migration', 'Softer rock below a resistant layer erodes faster, forming an overhang and plunge pool. Repeated collapse moves the waterfall upstream and leaves a steep-sided gorge.', 'Keep the sequence in order.', 'Rivers — option'],
    ['How does an ox-bow lake form?', 'A meander neck is cut through', 'Outer-bank erosion narrows the neck. During high flow the river takes a shorter route; deposition seals the old loop, leaving a separate curved lake.', 'Use both erosion and deposition.', 'Rivers — option'],
    ['How do natural levées form?', 'Coarser sediment is dropped beside the channel', 'When floodwater leaves the channel, friction reduces velocity. Heavier particles are deposited near the bank, and repeated floods build raised edges.', 'Explain why fine sediment travels farther across the floodplain.', 'Rivers — option'],
    ['What does a storm hydrograph show?', 'Rainfall and river discharge over time', 'The rising limb shows increasing discharge; peak discharge is the maximum. Lag time is the interval between peak rainfall and peak discharge.', 'Quote values and units when interpreting a graph.', 'Rivers — option'],
    ['Why can urbanisation increase flood risk?', 'Impermeable surfaces and rapid drainage', 'Roads and roofs reduce infiltration; drains carry water rapidly to channels. This can shorten lag time and increase peak discharge.', 'Link a land-use change to the hydrograph.', 'Rivers — option'],
    ['How do geology and relief affect flood risk?', 'Infiltration and runoff speed', 'Impermeable rocks limit infiltration, while steep slopes can move water quickly towards a river. Antecedent saturation and rainfall intensity also affect the response.', 'Use several factors when explaining a flood.', 'Rivers — option'],
    ['What are the trade-offs of dams and reservoirs?', 'Store floodwater but alter the valley', 'Controlled releases can reduce downstream peaks and provide water or electricity. Construction is costly and can displace people, flood habitats and trap sediment.', 'Balance social, economic and environmental effects.', 'Rivers — option'],
    ['How can floodplain zoning reduce flood losses?', 'Keep vulnerable development away from flood-prone land', 'Restricting buildings on floodplains lowers exposure and preserves space for water. It does not prevent rainfall or protect all existing development.', 'Distinguish reducing the hazard from reducing exposure.', 'Rivers — option'],
    ['How can river restoration help manage floods?', 'Restore storage and slow water movement', 'Reconnecting floodplains and restoring bends can hold water and reduce rapid downstream transfer. Land requirements and local flood risks must be considered.', 'Explain why slowing flow can protect downstream areas.', 'Rivers — option'],
    ['How do abrasion and plucking erode glacial landscapes?', 'Scraping and removal of rock blocks', 'Rock fragments in moving ice scrape the bed through abrasion. Ice can freeze onto fractured rock and pull pieces away through plucking.', 'Do not confuse glacial plucking with river transport.', 'Glaciation — option'],
    ['How does a corrie form?', 'Snow accumulates in a hollow and becomes ice', 'Rotational movement, abrasion and plucking deepen the basin and steepen its back wall. A rock lip may remain, retaining a tarn after melting.', 'Link each process to a part of the landform.', 'Glaciation — option'],
    ['How are arêtes and pyramidal peaks formed?', 'Erosion between neighbouring corries', 'Two corries eroding back towards each other can leave a narrow ridge called an arête. Several corries eroding around a mountain can leave a pointed pyramidal peak.', 'Explain the number and arrangement of corries.', 'Glaciation — option'],
    ['Why are glacial troughs U-shaped?', 'Ice erodes both the floor and sides', 'A glacier widens and deepens a former river valley. It cuts across interlocking spurs, leaving truncated spurs and a broad valley floor with steep sides.', 'Contrast with a river’s V-shaped upper valley.', 'Glaciation — option'],
    ['How do hanging valleys form?', 'Unequal erosion by main and tributary glaciers', 'A large main glacier erodes more deeply than a smaller tributary. After melting, the tributary valley is left above the main trough, sometimes producing a waterfall.', 'Use relative glacier size in the explanation.', 'Glaciation — option'],
    ['What are till, moraine and erratics?', 'Evidence of glacial transport and deposition', 'Till is unsorted material deposited directly by ice. Moraine is accumulated glacial debris; erratics are transported rocks resting on different local geology.', 'Distinguish till from sorted meltwater deposits.', 'Glaciation — option'],
    ['Why can tourism cause conflict in glaciated uplands?', 'Income and access compete with conservation', 'Visitors support jobs but can cause congestion, footpath erosion and disturbance. Path repair, public transport and visitor education can reduce impacts without removing tourism.', 'Apply to your named UK upland area.', 'Glaciation — option']
  ]);
  decks.find(d => d.id === 'cold-war').description = 'Edexcel P4 · Superpower relations and the Cold War, 1941–91. Origins, crises, détente and the end of Soviet control.';
  decks.find(d => d.id === 'medicine').description = 'Edexcel · Medicine in Britain, c1250–present, plus injuries, treatment and the trenches on the Western Front, 1914–18.';
  decks.find(d => d.id === 'natural-hazards').description = 'AQA Paper 1 · Tectonics, atmospheric circulation, tropical storms, UK weather and climate change. Add your school’s named examples.';
  decks.find(d => d.id === 'living-world').description = 'AQA Paper 1 · Ecosystems and rainforests, plus labelled hot-desert and cold-environment options. Revise the option your school teaches.';
  decks.find(d => d.id === 'uk-landscapes').description = 'AQA Paper 1 · UK overview, coasts, rivers and glaciation. Use Topic to revise the two options taught by your school.';
})();
